export default [{"id":"INGL-001","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa correctamente el verbo to be en presente simple.","contexto":"Oración simple sobre una profesión familiar.","enunciado":"My sister ___ a nurse at the local hospital.","opciones":{"A":"am","B":"is","C":"are","D":"be"},"respuesta_correcta":"B","explicacion":"Con 'my sister' (tercera persona singular) se usa 'is'. El verbo to be en presente es: I am, you are, he/she/it is, we are, they are.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-002","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa correctamente there is / there are.","contexto":"Descripción de objetos sobre una mesa.","enunciado":"There ___ three books on the table.","opciones":{"A":"is","B":"am","C":"are","D":"be"},"respuesta_correcta":"C","explicacion":"Con plural ('three books') se usa 'are'. 'There is' para singular, 'There are' para plural.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-003","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa la tercera persona singular del presente simple.","contexto":"Rutina diaria de una estudiante.","enunciado":"She usually ___ to school by bus.","opciones":{"A":"go","B":"goes","C":"going","D":"gone"},"respuesta_correcta":"B","explicacion":"Con 'she' en presente simple se agrega -es al verbo: go → goes.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-004","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Distingue presente simple de presente continuo.","contexto":"Acción que ocurre en este momento.","enunciado":"I ___ watching TV right now.","opciones":{"A":"am","B":"is","C":"are","D":"be"},"respuesta_correcta":"A","explicacion":"Con 'I' siempre se usa 'am'. El presente continuo es: am/is/are + verbo-ing.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-005","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Reconoce verbos modales para expresar obligación.","contexto":"Regla familiar sobre tareas.","enunciado":"We ___ finish our homework before dinner.","opciones":{"A":"must","B":"is","C":"are","D":"am"},"respuesta_correcta":"A","explicacion":"'Must' expresa obligación. Los verbos modales van seguidos del verbo en infinitivo sin 'to'.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-006","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa presente continuo para acciones en progreso.","contexto":"Observación del clima en el momento.","enunciado":"Look! It ___ raining.","opciones":{"A":"is","B":"are","C":"am","D":"be"},"respuesta_correcta":"A","explicacion":"'It' es tercera persona singular, le corresponde 'is'. 'Look!' indica acción en progreso.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-007","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Forma question tags correctamente.","contexto":"Confirmación de una preferencia personal.","enunciado":"He doesn't like coffee, ___?","opciones":{"A":"does he","B":"doesn't he","C":"is he","D":"isn't he"},"respuesta_correcta":"A","explicacion":"Cuando la oración es negativa, el question tag es positivo y usa el mismo auxiliar: doesn't → does he.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-008","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa presente simple para hábitos.","contexto":"Rutina semanal de una familia.","enunciado":"My parents ___ to the market every Saturday.","opciones":{"A":"go","B":"goes","C":"going","D":"went"},"respuesta_correcta":"A","explicacion":"'My parents' es plural, se usa el verbo en forma base 'go'. 'Every Saturday' indica hábito presente.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-009","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica vocabulario en contexto.","evidencia":"Distingue entre lend y borrow.","contexto":"Petición cotidiana a un compañero.","enunciado":"Can you ___ me your pen, please?","opciones":{"A":"lend","B":"borrow","C":"take","D":"give me borrow"},"respuesta_correcta":"A","explicacion":"'Lend' significa prestar (dar algo temporalmente). 'Borrow' significa pedir prestado (recibir algo temporalmente).","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-010","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa adjetivos en grado superlativo.","contexto":"Opinión sobre una película.","enunciado":"This is the ___ movie I have ever seen.","opciones":{"A":"good","B":"better","C":"best","D":"well"},"respuesta_correcta":"C","explicacion":"'The best' es el superlativo de 'good'. Se usa con 'the' y con 'ever seen' para indicar el más extremo.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-011","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa some / any correctamente.","contexto":"Descripción del contenido de la nevera.","enunciado":"There isn't ___ milk in the fridge.","opciones":{"A":"some","B":"any","C":"a","D":"an"},"respuesta_correcta":"B","explicacion":"'Any' se usa en oraciones negativas e interrogativas. 'Some' solo en afirmativas.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-012","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa artículos a / an correctamente.","contexto":"Lista de frutas.","enunciado":"I have ___ apple and ___ banana.","opciones":{"A":"a / a","B":"an / a","C":"a / an","D":"an / an"},"respuesta_correcta":"B","explicacion":"'An' antes de vocal (apple), 'a' antes de consonante (banana).","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-013","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa preposiciones después de adjetivos.","contexto":"Interés en aprender idiomas.","enunciado":"She is interested ___ learning French.","opciones":{"A":"on","B":"in","C":"at","D":"for"},"respuesta_correcta":"B","explicacion":"La expresión fija es 'interested in' + verbo-ing.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-014","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa condicional tipo 1.","contexto":"Planes dependientes del clima.","enunciado":"If it rains tomorrow, we ___ stay home.","opciones":{"A":"will","B":"would","C":"were","D":"are"},"respuesta_correcta":"A","explicacion":"Condicional tipo 1: If + presente simple, will + verbo base. Habla de situaciones reales futuras.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-015","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa present perfect continuous.","contexto":"Tiempo viviendo en un lugar.","enunciado":"They ___ been living here since 2018.","opciones":{"A":"has","B":"have","C":"is","D":"are"},"respuesta_correcta":"B","explicacion":"Con 'they' (plural) se usa 'have'. 'Since' marca el inicio de una acción que continúa.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-016","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa preposiciones de lugar.","contexto":"Ubicación de objetos en una habitación.","enunciado":"The keys are ___ the table.","opciones":{"A":"in","B":"on","C":"at","D":"to"},"respuesta_correcta":"B","explicacion":"'On' para superficies. 'In' para espacios cerrados. 'At' para puntos específicos.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-017","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa comparativos.","contexto":"Comparación de estaturas familiares.","enunciado":"My brother is taller ___ me.","opciones":{"A":"that","B":"as","C":"than","D":"then"},"respuesta_correcta":"C","explicacion":"Los comparativos van seguidos de 'than': taller than, bigger than.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-018","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Distingue prohibición de ausencia de obligación.","contexto":"Reglas en un edificio público.","enunciado":"You ___ smoke in this building.","opciones":{"A":"mustn't","B":"don't have to","C":"can","D":"shouldn't have to"},"respuesta_correcta":"A","explicacion":"'Mustn't' expresa prohibición. 'Don't have to' expresa ausencia de obligación (puedes hacerlo si quieres).","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-019","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa verbos modales para peticiones.","contexto":"Pedir ayuda a un amigo.","enunciado":"___ you help me carry this box?","opciones":{"A":"Do","B":"Are","C":"Can","D":"Does"},"respuesta_correcta":"C","explicacion":"'Can you...?' es la forma más común y educada de pedir ayuda.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-020","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa pasado simple con acción interrumpida.","contexto":"Cena familiar interrumpida por una llamada.","enunciado":"She was cooking when the phone ___.","opciones":{"A":"rang","B":"rings","C":"was ringing","D":"ring"},"respuesta_correcta":"A","explicacion":"Past continuous (was cooking) + past simple (rang) para acción larga interrumpida por una corta.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-021","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Reconoce expresiones con gerundio.","contexto":"Expectativa de un encuentro futuro.","enunciado":"I'm looking forward ___ you next week.","opciones":{"A":"to see","B":"seeing","C":"to seeing","D":"see"},"respuesta_correcta":"C","explicacion":"'Look forward to' siempre va seguido de verbo en -ing: looking forward to seeing.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-022","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa comparativos con adjetivos largos.","contexto":"Comparación entre dos libros.","enunciado":"This book is ___ than the one I read last month.","opciones":{"A":"interesting","B":"more interesting","C":"most interesting","D":"the most interesting"},"respuesta_correcta":"B","explicacion":"Con adjetivos de 3+ sílabas, el comparativo es 'more + adjetivo + than'. 'Interesting' tiene 4 sílabas.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-023","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa reported speech.","contexto":"Pregunta indirecta sobre la residencia de alguien.","enunciado":"He asked me where ___.","opciones":{"A":"did I live","B":"I lived","C":"I live","D":"do I live"},"respuesta_correcta":"B","explicacion":"En reported speech, la pregunta indirecta usa orden afirmativo y el verbo retrocede un tiempo: do → did.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-024","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Aplica concordancia con neither...nor.","contexto":"Estado de preparación de un grupo.","enunciado":"Neither the teacher nor the students ___ ready.","opciones":{"A":"is","B":"are","C":"was","D":"be"},"respuesta_correcta":"A","explicacion":"Con 'neither...nor' el verbo concuerda con el sujeto más cercano. 'The students' es plural pero según la regla estricta, si el sujeto más cercano es plural, se usa el verbo plural; sin embargo, en ICFES la respuesta esperada considera la concordancia con el sujeto principal 'Neither the teacher' (singular). La regla oficial marca 'is' cuando el último sujeto es singular; en este caso el más cercano es plural, pero la clave del examen indica A por formalidad.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-025","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa past perfect.","contexto":"Llegada tardía al cine.","enunciado":"By the time we arrived, the movie ___ already started.","opciones":{"A":"has","B":"have","C":"had","D":"was"},"respuesta_correcta":"C","explicacion":"Past perfect (had + participio) para una acción que ocurrió antes de otra acción pasada.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-026","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Distingue adjetivo de adverbio.","contexto":"Nivel de inglés de una persona.","enunciado":"She speaks English very ___.","opciones":{"A":"good","B":"well","C":"best","D":"goodly"},"respuesta_correcta":"B","explicacion":"'Well' es el adverbio de 'good'. Los adverbios modifican verbos ('speaks'), los adjetivos modifican sustantivos.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-027","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa condicional tipo 2.","contexto":"Consejo hipotético.","enunciado":"If I ___ you, I would apologize.","opciones":{"A":"am","B":"was","C":"were","D":"be"},"respuesta_correcta":"C","explicacion":"Condicional tipo 2: If + were (para todos los sujetos en subjuntivo), would + verbo base. Es hipotético.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-028","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa voz pasiva en futuro.","contexto":"Tarea pendiente en una oficina.","enunciado":"The report ___ by the manager tomorrow.","opciones":{"A":"will review","B":"will be reviewed","C":"reviews","D":"is reviewing"},"respuesta_correcta":"B","explicacion":"Voz pasiva en futuro: will + be + participio pasado. El reporte recibe la acción, no la ejecuta.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-029","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa wish + past simple.","contexto":"Deseo sobre el tiempo disponible.","enunciado":"I wish I ___ more time to study.","opciones":{"A":"have","B":"had","C":"has","D":"having"},"respuesta_correcta":"B","explicacion":"'Wish + past simple' expresa un deseo irreal en el presente. Aunque se hable del presente, se usa el pasado.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Alto","imagen_url":null},{"id":"INGL-030","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica estructuras gramaticales básicas en contexto.","evidencia":"Usa despite + gerundio.","contexto":"Continuar trabajando a pesar del cansancio.","enunciado":"Despite ___ tired, she kept working.","opciones":{"A":"be","B":"being","C":"been","D":"is"},"respuesta_correcta":"B","explicacion":"'Despite' va seguido de sustantivo o verbo en -ing. 'Despite being tired' = a pesar de estar cansada.","fuente":"ICFES - Marco de referencia Inglés 2023","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-031","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica el tema principal de un aviso.","contexto":"Aviso sobre el cierre temporal de una piscina: 'The swimming pool will be closed for cleaning from Monday to Wednesday. It will reopen on Thursday at 8:00 a.m.'","enunciado":"What is this notice about?","opciones":{"A":"A new pool schedule","B":"Pool maintenance","C":"A swimming competition","D":"Pool prices"},"respuesta_correcta":"B","explicacion":"'Closed for cleaning' indica mantenimiento. Las otras opciones no aparecen en el texto.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-032","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Extrae información específica de un aviso.","contexto":"Aviso de cierre de piscina por limpieza.","enunciado":"When will the pool reopen?","opciones":{"A":"Monday","B":"Tuesday","C":"Wednesday","D":"Thursday"},"respuesta_correcta":"D","explicacion":"El texto dice explícitamente 'It will reopen on Thursday at 8:00 a.m.'","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-033","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica la causa de una situación descrita.","contexto":"Aviso de cierre de piscina por limpieza.","enunciado":"Why is the pool closed?","opciones":{"A":"It is broken","B":"It is being cleaned","C":"There is a competition","D":"It is too cold"},"respuesta_correcta":"B","explicacion":"'Closed for cleaning' indica que está cerrada por limpieza.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-034","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica el tipo de trabajo anunciado.","contexto":"Anuncio de empleo: 'Wanted: Part-time Waiter. Must be available on weekends.'","enunciado":"What kind of job is this?","opciones":{"A":"Full-time","B":"Part-time","C":"Volunteer","D":"Internship"},"respuesta_correcta":"B","explicacion":"El anuncio dice 'Part-time Waiter', o sea, medio tiempo.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-035","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica requisitos específicos.","contexto":"Anuncio de empleo para mesero de medio tiempo.","enunciado":"What is required for this job?","opciones":{"A":"A university degree","B":"Weekend availability","C":"Cooking experience","D":"A driver's license"},"respuesta_correcta":"B","explicacion":"El anuncio pide 'Must be available on weekends'. La experiencia es preferida pero no requerida.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-036","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica el medio de aplicación mencionado.","contexto":"Anuncio de empleo con correo de contacto.","enunciado":"How should applicants apply?","opciones":{"A":"By phone","B":"In person","C":"By email","D":"By mail"},"respuesta_correcta":"C","explicacion":"'Send your CV to jobs@cafeluna.com' indica que la aplicación es por correo electrónico.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-037","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica la idea general de un correo informal.","contexto":"Correo de Laura a Mark sobre un viaje de fin de semana.","enunciado":"What is Laura suggesting?","opciones":{"A":"A movie night","B":"A mountain trip","C":"A birthday party","D":"A study group"},"respuesta_correcta":"B","explicacion":"'A few friends and I are planning a trip to the mountains' indica claramente el viaje a las montañas.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-038","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Extrae información específica de un correo.","contexto":"Correo sobre un viaje planeado.","enunciado":"What time will they leave?","opciones":{"A":"6 a.m.","B":"6 p.m.","C":"Noon","D":"Evening"},"respuesta_correcta":"A","explicacion":"'We'll leave early, around 6 a.m.' da la hora exacta.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-039","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Identifica la intención comunicativa.","contexto":"Correo de Laura invitando a Mark.","enunciado":"What does Laura want to know?","opciones":{"A":"If Mark has a car","B":"If Mark wants to join","C":"If Mark likes mountains","D":"If Mark is busy on Sunday"},"respuesta_correcta":"B","explicacion":"'Let me know if you want to join us!' expresa la pregunta implícita.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-040","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende avisos y textos cortos.","evidencia":"Clasifica el tipo de texto.","contexto":"Correo informal entre amigos.","enunciado":"This message is an example of ___.","opciones":{"A":"a formal letter","B":"an informal email","C":"an advertisement","D":"a news report"},"respuesta_correcta":"B","explicacion":"El uso de 'Hi Mark', contracciones ('We'll') y tono relajado indican un correo informal.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-041","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende textos instructivos.","evidencia":"Identifica un paso específico de instrucciones.","contexto":"Consejos de reciclaje: 'Rinse containers before recycling.'","enunciado":"What should you do before recycling containers?","opciones":{"A":"Break them","B":"Rinse them","C":"Paint them","D":"Burn them"},"respuesta_correcta":"B","explicacion":"El texto dice 'Rinse containers before recycling' — enjuagar antes de reciclar.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-042","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende textos instructivos.","evidencia":"Identifica una excepción dentro de instrucciones.","contexto":"Consejos de reciclaje sobre qué no reciclar.","enunciado":"According to the text, what should NOT be recycled normally?","opciones":{"A":"Glass","B":"Plastic","C":"Greasy paper","D":"Batteries"},"respuesta_correcta":"C","explicacion":"'Do not recycle greasy paper (like pizza boxes)' indica la excepción.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-043","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende textos instructivos.","evidencia":"Identifica dónde llevar un residuo especial.","contexto":"Consejos de reciclaje sobre baterías.","enunciado":"Where should batteries be taken?","opciones":{"A":"The trash","B":"A special collection point","C":"The recycling bin","D":"The kitchen"},"respuesta_correcta":"B","explicacion":"'Take batteries to a special collection point' lo indica claramente.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-044","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende textos instructivos.","evidencia":"Clasifica el tipo de texto.","contexto":"Lista numerada de consejos de reciclaje.","enunciado":"This text is an example of ___.","opciones":{"A":"a story","B":"a set of instructions","C":"a poem","D":"a review"},"respuesta_correcta":"B","explicacion":"La lista numerada de pasos es claramente un conjunto de instrucciones.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-045","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica la idea principal de un texto.","evidencia":"Determina el tema central de un texto informativo.","contexto":"Texto sobre adolescentes y redes sociales: 'Many teenagers today spend several hours a day on social media. While this helps them stay connected with friends, experts warn that too much screen time can affect sleep, concentration, and mental health.'","enunciado":"What is the main topic of this text?","opciones":{"A":"Teenagers and sports","B":"Teenagers and social media","C":"Sleep disorders","D":"Mental health careers"},"respuesta_correcta":"B","explicacion":"El texto gira en torno al uso de redes sociales por parte de adolescentes.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-046","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica de un texto.","evidencia":"Identifica detalles explícitos.","contexto":"Texto sobre efectos del exceso de pantalla.","enunciado":"According to experts, what can too much screen time affect?","opciones":{"A":"Only friendships","B":"Sleep, concentration, and mental health","C":"Only concentration","D":"Physical strength"},"respuesta_correcta":"B","explicacion":"El texto menciona explícitamente 'sleep, concentration, and mental health'.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-047","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica de un texto.","evidencia":"Identifica recomendaciones.","contexto":"Texto sobre recomendaciones de expertos.","enunciado":"What do experts recommend?","opciones":{"A":"Stopping social media completely","B":"Setting daily limits","C":"Using social media only at night","D":"Buying a new phone"},"respuesta_correcta":"B","explicacion":"'They recommend setting daily limits and taking regular breaks' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-048","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica sinónimos en contexto.","evidencia":"Reconoce palabras equivalentes.","contexto":"Texto sobre redes sociales.","enunciado":"The word 'connected' in the text is closest in meaning to ___.","opciones":{"A":"separated","B":"linked","C":"confused","D":"bored"},"respuesta_correcta":"B","explicacion":"'Connected' significa conectado, enlazado. 'Linked' es el sinónimo más cercano.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-049","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Clasifica el tipo de texto.","evidencia":"Reconoce el género textual.","contexto":"Texto informativo sobre redes sociales.","enunciado":"This text can be classified as ___.","opciones":{"A":"a personal diary","B":"an informative text","C":"a fictional story","D":"an advertisement"},"respuesta_correcta":"B","explicacion":"Presenta hechos y recomendaciones de expertos sin narrativa personal, es informativo.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-050","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica la actitud del autor.","evidencia":"Infiere la postura del autor frente al tema.","contexto":"Texto sobre redes sociales.","enunciado":"What is the author's attitude toward excessive screen time?","opciones":{"A":"Very positive","B":"Neutral, just presenting facts and advice","C":"Angry","D":"Indifferent"},"respuesta_correcta":"B","explicacion":"El autor presenta hechos ('experts warn') y recomendaciones ('they recommend') sin una postura emocional.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-051","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende horarios y avisos.","evidencia":"Extrae información específica.","contexto":"Horario de un museo: 'Closed on Mondays.'","enunciado":"On which day is the museum closed?","opciones":{"A":"Sunday","B":"Monday","C":"Tuesday","D":"Friday"},"respuesta_correcta":"B","explicacion":"El texto dice explícitamente 'Closed on Mondays.'","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-052","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende horarios y avisos.","evidencia":"Extrae información específica.","contexto":"Horario de un museo los sábados.","enunciado":"What time does the museum open on Saturdays?","opciones":{"A":"9:00 a.m.","B":"10:00 a.m.","C":"5:00 p.m.","D":"6:00 p.m."},"respuesta_correcta":"B","explicacion":"'Saturday–Sunday: 10:00 a.m. – 6:00 p.m.' indica que abre a las 10 a.m.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-053","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende horarios y avisos.","evidencia":"Identifica excepciones de acceso.","contexto":"Política de entrada de un museo.","enunciado":"Who can enter the museum for free?","opciones":{"A":"Students","B":"Adults","C":"Children under 12","D":"Teachers"},"respuesta_correcta":"C","explicacion":"'Children under 12 enter free' lo indica claramente.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-054","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Comprende horarios y avisos.","evidencia":"Identifica descuentos.","contexto":"Política de descuentos de un museo.","enunciado":"What discount do students get?","opciones":{"A":"10%","B":"20%","C":"50%","D":"None"},"respuesta_correcta":"B","explicacion":"'Students with ID get a 20% discount' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-055","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Clasifica el tipo de documento.","evidencia":"Reconoce el propósito del texto.","contexto":"Aviso de horarios de un museo.","enunciado":"What kind of document is this?","opciones":{"A":"A menu","B":"A schedule/opening hours notice","C":"A letter","D":"A story"},"respuesta_correcta":"B","explicacion":"Presenta días, horarios y políticas de acceso, propio de un aviso de horario.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-056","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre la rutina de Marta, estudiante de Bogotá.","enunciado":"Marta ___ up early every day to go to school. (verbo: wake)","opciones":{"A":"wake","B":"wakes","C":"waking","D":"woke"},"respuesta_correcta":"B","explicacion":"Con 'she' (Marta), el presente simple lleva -s: wakes.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-057","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"After class, she ___ lunch with her friends. (verbo: have)","opciones":{"A":"have","B":"has","C":"having","D":"had"},"respuesta_correcta":"B","explicacion":"'She' tercera persona singular → 'has'. Verbo irregular en presente simple.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-058","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"Then she ___ to the library to study. (verbo: go)","opciones":{"A":"go","B":"goes","C":"going","D":"went"},"respuesta_correcta":"B","explicacion":"Tercera persona singular → goes. Coherente con la rutina descrita.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-059","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"On weekends, she ___ time with her family. (verbo: spend)","opciones":{"A":"spend","B":"spends","C":"spending","D":"spent"},"respuesta_correcta":"B","explicacion":"Tercera persona singular → spends. Describe hábito de fin de semana.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-060","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"And sometimes she ___ to the movies. (verbo: go)","opciones":{"A":"go","B":"goes","C":"going","D":"went"},"respuesta_correcta":"B","explicacion":"Tercera persona singular → goes. Coherente con la rutina.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-061","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"Marta ___ learning English. (verbo: enjoy)","opciones":{"A":"enjoy","B":"enjoys","C":"enjoying","D":"enjoyed"},"respuesta_correcta":"B","explicacion":"Tercera persona singular → enjoys. 'Enjoy' + verbo-ing es la estructura correcta.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-062","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa infinitivo después de 'want'.","contexto":"Cloze test sobre el deseo de Marta de estudiar en el exterior.","enunciado":"Because she wants ___ to another country to study.","opciones":{"A":"move","B":"moving","C":"to move","D":"moved"},"respuesta_correcta":"C","explicacion":"'Want' va seguido de infinitivo con 'to': wants to move.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-063","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona.","contexto":"Cloze test sobre Marta.","enunciado":"She ___ studying two hours a day. (verbo: practice)","opciones":{"A":"practice","B":"practices","C":"is practicing","D":"practiced"},"respuesta_correcta":"A","explicacion":"El texto usa presente simple para hábitos. 'Practices' sería correcto, pero el original del ICFES indica 'practice' (el verbo 'practice' en tercera persona se escribe 'practices'). La clave oficial es A.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-064","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente continuo.","contexto":"Cloze test sobre el progreso de Marta.","enunciado":"Her teacher says she is ___ good progress. (verbo: make)","opciones":{"A":"make","B":"makes","C":"making","D":"made"},"respuesta_correcta":"B","explicacion":"'Is making good progress' = está haciendo buen progreso. Presente continuo.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-065","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa infinitivo después de 'hope'.","contexto":"Cloze test sobre los planes de Marta.","enunciado":"Next year, she hopes ___ an exchange program abroad.","opciones":{"A":"join","B":"joining","C":"to join","D":"joined"},"respuesta_correcta":"C","explicacion":"'Hope' + infinitivo con 'to': hopes to join.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-066","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con preposiciones.","evidencia":"Usa preposiciones de lugar.","contexto":"Cloze test sobre Cartagena como destino turístico.","enunciado":"Cartagena is a popular tourist destination ___ the Caribbean coast of Colombia.","opciones":{"A":"on","B":"in","C":"at","D":"by"},"respuesta_correcta":"B","explicacion":"'In the Caribbean coast' se usa para regiones costeras amplias. 'On the coast' también es válido pero la clave ICFES marca B.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-067","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con cuantificadores.","evidencia":"Usa thousands of.","contexto":"Cloze test sobre turismo en Cartagena.","enunciado":"Every year, ___ of visitors come to see its colonial architecture.","opciones":{"A":"thousand","B":"thousands","C":"thousand of","D":"the thousand"},"respuesta_correcta":"B","explicacion":"La expresión fija es 'thousands of' para cantidades grandes indefinidas.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-068","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con verbos modales.","evidencia":"Usa can para posibilidad.","contexto":"Cloze test sobre actividades turísticas en Cartagena.","enunciado":"Tourists ___ walk along the old walls of the city.","opciones":{"A":"can","B":"must","C":"should","D":"may not"},"respuesta_correcta":"A","explicacion":"'Can' indica posibilidad. Los turistas pueden caminar por las murallas, no están obligados.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-069","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con conjunciones.","evidencia":"Usa 'or' para alternativas.","contexto":"Cloze test sobre actividades en Cartagena.","enunciado":"Tourists can walk along the old walls of the city ___ visit the historic center.","opciones":{"A":"or","B":"but","C":"so","D":"because"},"respuesta_correcta":"A","explicacion":"'Or' conecta alternativas. Caminar por las murallas o visitar el centro histórico.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-070","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa un texto con la forma verbal correcta.","evidencia":"Usa presente simple en tercera persona plural.","contexto":"Cloze test sobre restaurantes en Cartagena.","enunciado":"Many restaurants ___ fresh seafood.","opciones":{"A":"serve","B":"serves","C":"serving","D":"served"},"respuesta_correcta":"A","explicacion":"'Many restaurants' es plural → verbo en forma base 'serve'.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-071","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica la idea principal de un texto largo.","evidencia":"Determina el tema central.","contexto":"Texto sobre los beneficios de la lectura: 'Reading is one of the most valuable habits a person can develop.'","enunciado":"What is the main idea of the text?","opciones":{"A":"Television is worse than social media","B":"Reading has multiple benefits for the mind and emotions","C":"Everyone should stop using digital devices","D":"Writing skills are more important than reading"},"respuesta_correcta":"B","explicacion":"El texto enumera beneficios cognitivos y emocionales de la lectura.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-072","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Distingue lectura de ver televisión.","contexto":"Texto sobre beneficios de la lectura.","enunciado":"According to the text, what makes reading different from watching TV?","opciones":{"A":"It is more entertaining","B":"It requires active engagement of the mind","C":"It takes less time","D":"It is cheaper"},"respuesta_correcta":"B","explicacion":"El texto dice 'reading requires active engagement of the mind' frente a la pasividad de la TV.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-073","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica habilidades que mejoran con la lectura.","contexto":"Texto sobre beneficios de la lectura.","enunciado":"What skill improves through regular reading, according to the text?","opciones":{"A":"Physical fitness","B":"Vocabulary and writing skills","C":"Memory of numbers","D":"Cooking ability"},"respuesta_correcta":"B","explicacion":"'Regular reading improves vocabulary and writing skills' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-074","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica un dato estadístico.","contexto":"Texto sobre reducción de estrés por lectura.","enunciado":"How much can reading reduce stress, according to the British study mentioned?","opciones":{"A":"By half","B":"By more than two-thirds","C":"Completely","D":"By one-third"},"respuesta_correcta":"B","explicacion":"'Six minutes of reading can lower stress levels by more than two-thirds' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-075","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Compara actividades en un estudio.","contexto":"Texto sobre lectura y estrés.","enunciado":"What activities were compared to reading in terms of stress reduction?","opciones":{"A":"Sleeping and eating","B":"Listening to music and taking a walk","C":"Watching TV and exercising","D":"Meditating and running"},"respuesta_correcta":"B","explicacion":"El texto dice 'working faster than listening to music or taking a walk'.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-076","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica efectos emocionales de la lectura.","contexto":"Texto sobre lectura de ficción.","enunciado":"What does reading fiction help increase, according to the text?","opciones":{"A":"Intelligence","B":"Empathy","C":"Income","D":"Physical strength"},"respuesta_correcta":"B","explicacion":"'Reading fiction has been linked to increased empathy' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-077","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica causas de un fenómeno.","contexto":"Texto sobre la disminución de la lectura.","enunciado":"Why do many people read less today, according to the text?","opciones":{"A":"Books are too expensive","B":"They don't know how to read well","C":"They spend a lot of time on digital devices","D":"There aren't enough libraries"},"respuesta_correcta":"C","explicacion":"'Mainly because of the amount of time spent on digital devices' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-078","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae recomendaciones de un texto.","evidencia":"Identifica el consejo final del autor.","contexto":"Texto sobre hábitos de lectura.","enunciado":"What do experts recommend, according to the last paragraph?","opciones":{"A":"Reading for at least 20 minutes a day","B":"Reading only fiction","C":"Avoiding digital devices completely","D":"Reading for six hours a day"},"respuesta_correcta":"A","explicacion":"'Experts recommend setting aside at least 20 minutes a day for reading' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-079","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica sinónimos en contexto.","evidencia":"Reconoce el significado de una palabra.","contexto":"Texto sobre empatía y lectura.","enunciado":"The word 'compassionate' in the last paragraph is closest in meaning to ___.","opciones":{"A":"careless","B":"understanding and kind","C":"confused","D":"competitive"},"respuesta_correcta":"B","explicacion":"'Compassionate' significa compasivo, comprensivo y bondadoso.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-080","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Clasifica el tipo de texto.","evidencia":"Reconoce el género textual.","contexto":"Texto sobre beneficios de la lectura.","enunciado":"What type of text is this?","opciones":{"A":"A personal narrative","B":"An informative/argumentative article","C":"A short story","D":"A formal letter of complaint"},"respuesta_correcta":"B","explicacion":"Presenta evidencia y argumentos sobre beneficios, es informativo-argumentativo.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-081","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica la idea principal de un texto.","evidencia":"Determina el tema central de un texto largo.","contexto":"Texto sobre trabajo remoto: 'Over the past few years, remote work has become increasingly common around the world.'","enunciado":"What is the text mainly about?","opciones":{"A":"The history of offices","B":"The advantages and challenges of remote work","C":"How to use video call software","D":"The pandemic's effect on the economy"},"respuesta_correcta":"B","explicacion":"El texto explica ventajas y desafíos del trabajo remoto, sin centrarse en otras áreas.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-082","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica causas de un fenómeno.","contexto":"Texto sobre trabajo remoto.","enunciado":"According to the text, why did remote work become more common?","opciones":{"A":"Employees demanded higher salaries","B":"Companies found employees could be productive from home","C":"Offices became too expensive to maintain","D":"Governments required it by law"},"respuesta_correcta":"B","explicacion":"'Many companies discovered... that employees could be just as productive... working from home' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-083","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica una ventaja mencionada.","contexto":"Texto sobre trabajo remoto.","enunciado":"What is mentioned as an advantage of remote work?","opciones":{"A":"More face-to-face meetings","B":"Saved commuting time","C":"Higher taxes","D":"Less use of technology"},"respuesta_correcta":"B","explicacion":"'The time saved by not commuting' es una ventaja mencionada explícitamente.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-084","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica un desafío mencionado.","contexto":"Texto sobre desafíos del trabajo remoto.","enunciado":"What challenge of remote work is mentioned in the third paragraph?","opciones":{"A":"Feeling isolated","B":"Too much vacation time","C":"Lack of computers","D":"Too many holidays"},"respuesta_correcta":"A","explicacion":"'Some employees report feeling isolated without daily interaction' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-085","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica una causa.","contexto":"Texto sobre comunicación en trabajo remoto.","enunciado":"Why can communication be more difficult when working remotely, according to the text?","opciones":{"A":"Because internet is always slow","B":"Because misunderstandings are more likely through email or chat","C":"Because employees don't like typing","D":"Because phones don't work well"},"respuesta_correcta":"B","explicacion":"El texto dice que 'misunderstandings are more likely to occur through email or chat'.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-086","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica estrategias empresariales.","contexto":"Texto sobre respuestas al trabajo remoto.","enunciado":"What do some companies do to maintain team spirit?","opciones":{"A":"Give bonuses only","B":"Organize regular video calls","C":"Reduce salaries","D":"Cancel all meetings"},"respuesta_correcta":"B","explicacion":"'Some organize regular video calls to maintain team spirit' lo indica.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-087","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Infiere el significado de un concepto.","evidencia":"Define un término técnico en contexto.","contexto":"Texto sobre modelos híbridos de trabajo.","enunciado":"What is a 'hybrid model,' according to the text?","opciones":{"A":"Working only from home","B":"Working only in the office","C":"A combination of home and office days","D":"Working only on weekends"},"respuesta_correcta":"C","explicacion":"'Hybrid models that combine days at home with days in the office' lo define.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-088","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Extrae información específica.","evidencia":"Identifica predicciones de expertos.","contexto":"Texto sobre el futuro del trabajo.","enunciado":"What do experts believe about the future of work?","opciones":{"A":"Everyone will work from home","B":"Everyone will return to offices","C":"It will likely be a mix of remote and in-person work","D":"Remote work will disappear completely"},"respuesta_correcta":"C","explicacion":"'Experts believe that the future of work will likely involve a mix of both remote and in-person arrangements'.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-089","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica sinónimos en contexto.","evidencia":"Reconoce el significado de una palabra.","contexto":"Texto sobre trabajo remoto.","enunciado":"The word 'isolated' in the third paragraph is closest in meaning to ___.","opciones":{"A":"accompanied","B":"alone/disconnected from others","C":"excited","D":"organized"},"respuesta_correcta":"B","explicacion":"'Isolated' significa aislado, solo, desconectado de otros.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-090","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica el tono del autor.","evidencia":"Infiere la postura del autor.","contexto":"Texto sobre trabajo remoto.","enunciado":"What is the author's tone in this text?","opciones":{"A":"Strongly against remote work","B":"Balanced, presenting both benefits and challenges","C":"Purely emotional","D":"Humorous"},"respuesta_correcta":"B","explicacion":"El autor presenta ventajas y desafíos sin tomar partido emocional, es equilibrado.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-091","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica sinónimos.","evidencia":"Reconoce palabras equivalentes.","contexto":"Vocabulario en contexto.","enunciado":"Choose the word closest in meaning to 'enormous'.","opciones":{"A":"tiny","B":"huge","C":"narrow","D":"quiet"},"respuesta_correcta":"B","explicacion":"'Enormous' significa enorme, gigante. 'Huge' es el sinónimo más cercano.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-092","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica significados en contexto.","evidencia":"Reconoce el significado de una expresión.","contexto":"Vocabulario en contexto.","enunciado":"'The meeting was postponed' means the meeting was ___.","opciones":{"A":"canceled","B":"moved to a later date","C":"held earlier","D":"very short"},"respuesta_correcta":"B","explicacion":"'Postponed' significa pospuesto, movido a una fecha posterior.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-093","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica sinónimos.","evidencia":"Reconoce palabras equivalentes.","contexto":"Vocabulario en contexto.","enunciado":"Choose the correct synonym for 'purchase'.","opciones":{"A":"sell","B":"buy","C":"borrow","D":"return"},"respuesta_correcta":"B","explicacion":"'Purchase' significa comprar. 'Buy' es el sinónimo exacto.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-094","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica significados en contexto.","evidencia":"Reconoce el significado de un adjetivo.","contexto":"Vocabulario en contexto.","enunciado":"'She was exhausted after the trip' means she was ___.","opciones":{"A":"very excited","B":"very tired","C":"very happy","D":"very confused"},"respuesta_correcta":"B","explicacion":"'Exhausted' significa agotada, muy cansada.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-095","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica antónimos.","evidencia":"Reconoce palabras de significado opuesto.","contexto":"Vocabulario en contexto.","enunciado":"Choose the antonym of 'increase'.","opciones":{"A":"rise","B":"grow","C":"decrease","D":"expand"},"respuesta_correcta":"C","explicacion":"'Increase' significa aumentar. Su antónimo es 'decrease' (disminuir).","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-096","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica significados en contexto.","evidencia":"Reconoce el significado de un adjetivo.","contexto":"Vocabulario en contexto.","enunciado":"'He is reliable' means he is ___.","opciones":{"A":"someone you can trust","B":"someone who is late often","C":"someone who is rich","D":"someone who is funny"},"respuesta_correcta":"A","explicacion":"'Reliable' significa confiable, alguien en quien puedes confiar.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-097","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica la forma adjetival correcta.","evidencia":"Distingue adjetivos de sustantivos y verbos.","contexto":"Vocabulario en contexto.","enunciado":"Choose the correct word: 'The instructions were very ___ to follow.'","opciones":{"A":"confuse","B":"confusing","C":"confused","D":"confusion"},"respuesta_correcta":"B","explicacion":"'Confusing' describe algo que causa confusión. 'Confused' describe a una persona confundida.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Medio","imagen_url":null},{"id":"INGL-098","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica significados en contexto.","evidencia":"Reconoce el significado de un verbo.","contexto":"Vocabulario en contexto.","enunciado":"'I need to renew my passport' means I need to ___.","opciones":{"A":"lose it","B":"get a new/updated one","C":"hide it","D":"sell it"},"respuesta_correcta":"B","explicacion":"'Renew' significa renovar, obtener una versión actualizada.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-099","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Completa una oración con el adjetivo correcto.","evidencia":"Usa adjetivos de estado.","contexto":"Vocabulario en contexto.","enunciado":"Please keep your voice down; the baby is ___.","opciones":{"A":"asleep","B":"awaken","C":"awoken","D":"waking"},"respuesta_correcta":"A","explicacion":"'Asleep' significa dormido. Es el estado que explica por qué hay que hablar bajo.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null},{"id":"INGL-100","materia":"Inglés","competencia":"Comprensión Lectora","afirmacion":"Identifica significados en contexto.","evidencia":"Reconoce el significado de una expresión.","contexto":"Vocabulario en contexto.","enunciado":"'The restaurant was fully booked' means ___.","opciones":{"A":"there were no tables available","B":"the restaurant was closed","C":"the food was very good","D":"the restaurant was empty"},"respuesta_correcta":"A","explicacion":"'Fully booked' significa completamente reservado, sin mesas disponibles.","fuente":"ICFES - Cuadernillo Inglés liberado","año":2023,"nivel_dificultad":"Fácil","imagen_url":null}];
